INSERT INTO `posts` VALUES (1,2,'dasdasdasd-adsadsa','dasdasdasd ádsadsa',1,'<ul><li style=\"text-align:center;\"><strong>BẢNG PHÂN TÍCH DỮ LIỆU TỪ HỆ THỐNG</strong></li><li style=\"text-align:center;\"><i>(Tổng hợp từ báo cáo sự cố các dự án PMC – giai đoạn 2025)</i></li><li><strong>I. CÁC DỰ ÁN CÓ SỐ LƯỢNG SỰ CỐ ĐÁNG LƯU Ý TRONG NĂM 2025</strong></li><li>Căn cứ tổng hợp dữ liệu sự cố vận hành trong năm 2025, một số dự án ghi nhận số lượng sự cố ở mức đáng lưu ý, bao gồm:</li></ul><p>ádasd</p><ul><li>Nhận xét &amp; cảnh báosdaddsa<strong>đâsd<u>đâsd</u></strong></li></ul><figure class=\"image image-style-align-right\"><img src=\"https://images.pexels.com/photos/674010/pexels-photo-674010.jpeg\"></figure>',0,0,'2026-01-06 07:36:25','2026-01-06 09:55:42'),(2,2,'dad-adasd','đád ádasd',1,'<p style=\"text-align:center;\">2.1.&nbsp; Chấm công hàng ngày</p><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Đối với các nhân sự mới hoặc không có trong danh sách, anh chị vui lòng khai báo nhân sự lên trang quản lý nhân sự nhà thầu <a href=\"https://dbedu.pmcweb.vn/\">dbedu.pmcweb.vn</a></p><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Các thông tin nhân sự sẽ được đồng bộ theo thông tin nhân sự trên trang <a href=\"https://dbedu.pmcweb.vn/\">dbedu.pmcweb.vn</a> (Quản lý thông tin nhân sự nhà thầu)</p><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Các ca làm việc sẽ được lấy theo các ca được khai báo trên web: <a href=\"https://checklist.pmcweb.vn\">https://checklist.pmcweb.vn</a></p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Sử dụng tài khoản giám đốc dự án truy cập vào mục “An ninh” =&gt; “Chấm công”</p><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Ấn vào ô để đánh dấu X hoặc nhập thời gian cụ thể theo hướng dẫn phía trên sau cùng sẽ chọn “Lưu” để hoàn tất</p><h3>2.2.&nbsp;&nbsp;&nbsp; Cập nhật nhân sự nghỉ việc</h3><h3>2.3.&nbsp;&nbsp;&nbsp; Cập nhật nhân sự mới</h3><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Đối với các nhân sự mới cần sử dụng form upload nhân sự nhà thầu để cập nhật các thông tin của nhân sự nhà thấu mới lên trang quản lý</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Form và hướng dẫn: <a href=\"https://pmcwebvn-my.sharepoint.com/:w:/g/personal/phongsohoa_pmcweb_vn/EZbcrrcMFMFEj_PiGXXLSicBSPPAMDY5e5WngKMwiR7aSA?e=tiRDSI\">Nhân sự nhà thầu</a><br>&nbsp;</p><h2>3.&nbsp;&nbsp; Báo cáo quản lý công cụ dụng cụ</h2><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Sử dụng tài khoản giám đốc dự án để báo cáo</p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Truy cập vào mục “Báo cáo công cụ”, tại đây có thể xem được các báo cáo của các ngày hôm trước hoặc tạo báo cáo mới cho ngày hiện tại</p><p style=\"text-align:justify;\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Để tạo báo cáo mới chọn mục “Tạo báo cáo mới” =&gt; tại đây sẽ mở ra 1 cửa số với tên các công cụ, nhập các đầu mục như: SL yêu cầu, SL thực tế, Tình trạng, ghi chú, … =&gt; Chọn “Tạo báo cáo” để hoàn tất</p><p>&nbsp;</p><h2>4.&nbsp;&nbsp; Báo cáo an ninh vi phạm</h2><h3>4.1.&nbsp;&nbsp;&nbsp; Trường hợp không có nhân sự vi phạm</h3><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Đối với trường hợp không có nhân sự vi phạm thì cứ mỗi ngày trong khung&nbsp; giờ từ 16h đến 18h trong mục báo cáo sẽ có phím tắt <strong>“Báo cáo nhanh”</strong> khi đó chỉ cần chọn thì báo cáo an ninh vi phạm sẽ được gửi với số lượng vi phạm là 0</p><h3>4.2.&nbsp;&nbsp;&nbsp; Trường hợp có nhân sự vi phạm</h3><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p style=\"text-align:center;\"><i>Giao diện chính “Báo cáo an ninh vi phạm”</i></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Truy cập vào mục “Quản lý dịch vụ AN” =&gt; “Báo cáo ngày” =&gt; “Vi phạm”</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (4): Danh sách nhân sự nhà thầu – dữ liệu nhân sự được lấy trực tiếp từ trang quản lý nhân sự nhà thầu</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (5) Phân quyền tạo báo cáo AN vi phạm</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (6) Tạo báo cáo mới – khi tạo báo cáo AN vi phạm</p><p>&nbsp;</p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Chọn (6) – Tạo báo cáo mới =&gt; xuất hiện giao diện “Tạo báo cáo an ninh vi phạm” =&gt; Tại đây nhập đầy đủ thông tin của nhân sự vi phạm, có thể tải file biên bản và hình ảnh vi phạm</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Nếu nhiều hơn 1 nhân sự vi phạm có thể chọn mục (1) – thêm</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Khi đã nhập đầy đủ chọn (2) – tạo báo cáo để hoàn tất báo cáo</p><h2>5.&nbsp;&nbsp; Báo cáo đào tạo giao ca</h2><h3>5.1.&nbsp;&nbsp;&nbsp; Phân quyền báo cáo đào tạo giao ca</h3><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Sử dụng tài khoản giám đốc</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Truy cập vào mục “Quản lý dịch vụ AN” =&gt; Chọn “Đào tạo giao ca”, tại màn hình ta chọn vào mục “Phân quyền” (như trong ảnh). Tích chọn các tài khoản cho phép báo cáo</p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Sẽ có thông báo “Đã phân quyền” như vậy là thành công</p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure><p>&nbsp;</p><h3>5.2.&nbsp;&nbsp;&nbsp; Tạo báo cáo mới</h3><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tại màn hình “Đào tạo giao ca” chọn mục “Tạo báo cáo mới” =&gt; sẽ hiện lên form nhập để Anh/chị điền các thông tin gồm:</p><p>o&nbsp;&nbsp; Người đào tạo</p><p>o&nbsp;&nbsp; Nhân sự an ninh tham gia</p><p>o&nbsp;&nbsp; Nội dung đào tạo</p><p>o&nbsp;&nbsp; Link video (sẽ là link video chia sẻ đã được dự án quay lại và tải lên OneDrive)</p><p>o&nbsp;&nbsp; Thêm đường dẫn video (Thêm ô nhập với đường dẫn video với trường hợp nhiều hơn 1 video)</p><p>o&nbsp;&nbsp; Sau khi nhập đầy đủ chọn “Lưu” để hoàn tất báo cáo</p><figure class=\"image\"><img src=\"data:image/png;base64,\"></figure>',0,0,'2026-01-06 10:10:25','2026-01-06 10:12:58'),(3,2,'afsafasffaf-adasdasd','afsafasffaf-ádasdasd',0,'                                        <h3>Start writing your post...</h3>\r\n                                        <p>Type your content here. You can use the toolbar above to format your te<b style=\"text-align: center;\"><span style=\"font-size:14.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">HƯỚNG\r\nDẪN BÁO</span></b><b style=\"text-align: center;\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:150%;\r\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:VI\"> CÁO NGÀY DỊCH VỤ AN\r\nNINH</span></b></p><p class=\"MsoTocHeading\" align=\"center\" style=\"text-align:center;line-height:150%\"><b><span style=\"font-family:&quot;Times New Roman&quot;,serif;color:black;mso-themecolor:text1\">Mục\r\n lục<o:p></o:p></span></b><span style=\"font-size:11.0pt;line-height:150%;\r\n font-family:&quot;Times New Roman&quot;,serif;mso-ascii-font-family:Calibri;mso-ascii-theme-font:\r\n minor-latin;mso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;\r\n mso-hansi-font-family:Calibri;mso-hansi-theme-font:minor-latin;mso-bidi-theme-font:\r\n minor-bidi;color:windowtext\"><w:sdtpr></w:sdtpr></span></p><p class=\"MsoToc2\"><!--[if supportFields]><span\r\n style=\'mso-element:field-begin\'></span><span\r\n style=\'mso-spacerun:yes\'> </span>TOC \\o &quot;1-3&quot; \\h \\z \\u <span\r\n style=\'mso-element:field-separator\'></span><![endif]--><a href=\"file:///C:/Users/MANH/AppData/Local/Temp/Zalo%20Temp/TempDownloads/