 </span><span style=\"color: #ce9178;\">\'í\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'i\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ị\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'i\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ỉ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'i\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ĩ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'i\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><span style=\"color: #ce9178;\">\'ò\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ó\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ọ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ỏ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'õ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><span style=\"color: #ce9178;\">\'ô\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ồ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ố\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ộ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ổ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ỗ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><span style=\"color: #ce9178;\">\'ơ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ờ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ớ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ợ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ở\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'ỡ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'o\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&n