><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ã\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><span style=\"color: #ce9178;\">\'Â\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ầ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ấ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ậ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ẩ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ẫ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">,</span></div><div><span style=\"color: #d4d4d4;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><span style=\"color: #ce9178;\">\'Ă\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ằ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d4d4d4;\">, </span><span style=\"color: #ce9178;\">\'Ắ\'</span><span style=\"color: #d4d4d4;\"> =&gt; </span><span style=\"color: #ce9178;\">\'A\'</span><span style=\"color: #d